import React, {useState} from 'react';

const logo = {
  alt: 'Old Mate Cranes & Rigging',
  url: 'logo01.png',
  width: 240,
  href: 'http://oldmatecranes.com.au/'
};

const menu = {
  link1:{
    copy:'home',
    url: 'http://oldmatecranes.com.au/'
  },
  link2:{
    copy:'about us',
    url:'#aboutus'
  },
  link3:{
    copy:'contact',
    url: '#contact'
  },
  link4:{
    copy:'services',
    url:'#services'
  },
  link5:{
    copy:'safety',
    url: '#safety'
  },
  link6:{
    copy:'industrial',
    url:'#industrial'
  },
  link7:{
    copy:'civil',
    url:'#civil'
  }
};


const [isNavbarExpanded, setIsNavbarExpanded] = useState(false);

const toggleNavbar = () => {
setIsNavbarExpanded(!isNavbarExpanded);
};



const Menu = () => {



  return(

  <section>
        <nav className='navbar navbar-expand-lg bg-body-tertiary fixed-top'>
          <div className='container-fluid'>
          <a className='navbar-brand' href={logo.href}>
          <img src={logo.url} alt={logo.alt} width={logo.width} />
          </a>
            <button className='navbar-toggler' type='button' data-bs-toggle='collapse' data-bs-target='#navbarNavAltMarkup' aria-controls='navbarNavAltMarkup' aria-expanded='false' aria-label='Toggle navigation'>
              <span className='navbar-toggler-icon'></span>
            </button>
            <div className='collapse navbar-collapse flex-row-reverse' id='navbarNavAltMarkup'>
              <div className='navbar-nav menu-links'>
              <a href={menu.link1.url}>{menu.link1.copy} onClick={toggleNavbar}</a>
              <a href={menu.link2.url}>{menu.link2.copy}</a>
              <a href={menu.link3.url}>{menu.link3.copy}</a>
              <a href={menu.link4.url}>{menu.link4.copy}</a>
              <a href={menu.link5.url}>{menu.link5.copy}</a>
              <a href={menu.link6.url}>{menu.link6.copy}</a>
              <a href={menu.link7.url}>{menu.link7.copy}</a>
              </div>
            </div>
          </div>
        </nav>

      </section>
)};

export default Menu;
